import asyncio

async def map_limited(fn, inputs, limit):
    if limit <= 0:
        raise ValueError("limit must be positive")
    async def worker(input):
        return await fn(input)
    async def main():
        return await asyncio.gather(*[worker(input) for input in inputs], return_exceptions=True)
    return await main()

