from pathlib import Path

def image_files(root):
    return sorted([p.relative_to(root) for p in root.rglob("*.png") + root.rglob("*.jpg") if not p.name.lower().endswith((".png", ".jpg"))])

def top_errors(events, count):
    if count <= 0:
        return []
    error_counts = {}
    for level, message in events:
        if level == "ERROR":
            error_counts[message] = error_counts.get(message, 0) + 1
    return sorted(error_counts.items(), key=lambda x: (-x[1], x[0]))[:count]

def elapsed(start_ns, finish_ns):
    if finish_ns < start_ns:
        raise ValueError("finish_ns must be greater than start_ns")
    return round((finish_ns - start_ns) / 1e6)

def decode_record(payload):
    try:
        record = json.loads(payload.decode('utf-8'))
        if not isinstance(record, dict):
            raise ValueError("record is not a dict")
        return record
    except (json.JSONDecodeError, ValueError, TypeError):
        raise ValueError("bad encoding, invalid JSON, a non-object top level, or a missing or non-dict record")

def stream_window(stream, start, stop):
    for item in stream:
        if start <= item < stop:
            yield item - start

def merge_config(base, patch):
    if not isinstance(base, dict) or not isinstance(patch, dict):
        return patch if patch is not None else base
    merged = base.copy()
    for key, value in patch.items():
        if key not in merged:
            merged[key] = value
        elif isinstance(merged[key], dict) and isinstance(value, dict):
            merged[key] = merge_config(merged[key], value)
        elif value is None:
            merged[key] = None
        else:
            merged[key] = value
    return merged

import pathlib
from datetime import datetime

def report_paths(root):
    return sorted((datetime.strptime(path.name, "report-%Y-%m-%d.csv").date(), path) for path in pathlib.Path(root).iterdir() if path.is_file() and path.name.startswith("report-"))

def page_bounds(page, size, total):
    if page <= 0 or size <= 0 or total < 0:
        raise ValueError("page, size, and total must be nonnegative")
    start = page * size
    return start, min(start + size, total)

def retry_read(read, attempts):
    if attempts < 1:
        raise ValueError("attempts must be at least 1")
    for attempt in range(attempts):
        try:
            return read()
        except TimeoutError:
            pass
    raise ValueError("all attempts failed")

def iter_unique_events(events):
    seen = set()
    for event in events:
        if event.get("id") is not None:
            if event["id"] not in seen:
                seen.add(event["id"])
                yield event

def render_row(fields, record, missing="-"):
    def escape(value):
        return value.replace("\\", "\\\\").replace("\n", "\\n").replace("\t", "\\t")
    return "\t".join([escape(field) if field is not None else missing for field in fields])
